from __future__ import annotations

import os
from pathlib import Path
from typing import Final

PACKAGE_NAME: Final = "artifact_manager"


def _resolve_root(default: str) -> Path:
    base = Path(default)
    try:
        return base.resolve()
    except FileNotFoundError:
        return base


def get_artifacts_root() -> Path:
    """Return the configured artifacts root directory."""
    return _resolve_root(os.getenv("ARTIFACT_ENGINE_ROOT", "artifacts"))


def get_registry_path() -> Path:
    """Return the configured registry file path."""
    return _resolve_root(os.getenv("ARTIFACT_ENGINE_REGISTRY", "locations.json"))


# Deprecated: kept for backwards compatibility
ARTIFACTS_ROOT: Final[Path] = Path("artifacts")
REGISTRY_PATH: Final[Path] = Path("locations.json")


__all__ = [
    "ARTIFACTS_ROOT",
    "REGISTRY_PATH",
    "get_artifacts_root",
    "get_registry_path",
]

from __future__ import annotations

import logging
from contextlib import asynccontextmanager
from typing import Any, AsyncIterator, Dict, List, Optional

from fastapi import Body, FastAPI, File, Form, HTTPException, Path as ApiPath, UploadFile
from fastapi.responses import FileResponse, JSONResponse, Response, StreamingResponse
from pydantic import BaseModel, Field

from . import get_artifacts_root
from .registry import (
    RegistryError,
    RegistryValidationException,
    ValidationError,
    get_registry_entries,
    list_all_locations,
    load_registry,
    validate_registry,
)
from .search import search_artifacts
from .storage import (
    ArtifactConflictError,
    ArtifactNotFoundError,
    InvalidArtifactExtensionError,
    InvalidArtifactPathError,
    StorageError,
    get_artifact_content_path,
    get_artifact_metadata,
    store_artifact,
)

logger = logging.getLogger(__name__)


class SearchRequest(BaseModel):
    domains: Optional[List[str]] = None
    locations: Optional[List[str]] = None
    tags: Optional[List[str]] = None
    topics: Optional[List[str]] = None
    keywords: Optional[List[str]] = None
    limit: int = Field(50, gt=0)
    offset: int = Field(0, ge=0)


class RegistryValidateRequest(BaseModel):
    locations: Dict[str, Dict[str, Any]]


def _error_response(
    status_code: int, error_code: str, message: str, details: Optional[Dict[str, Any]] = None
) -> JSONResponse:
    payload: Dict[str, Any] = {
        "error": error_code,
        "message": message,
        "details": details or {},
    }
    return JSONResponse(status_code=status_code, content=payload)


@asynccontextmanager
async def lifespan(app: FastAPI) -> AsyncIterator[None]:
    """Load and validate registry at startup."""
    logger.info("Loading registry at startup...")
    try:
        load_registry()
        logger.info("Registry loaded successfully")
    except RegistryValidationException as exc:
        logger.error("Registry validation failed at startup: %s", exc)
        raise
    except RegistryError as exc:
        logger.error("Failed to load registry at startup: %s", exc)
        raise
    yield
    # Cleanup on shutdown (none needed currently)


def create_app() -> FastAPI:
    app = FastAPI(title="Artifact Engine V1", lifespan=lifespan)

    @app.post("/artifact/store", status_code=201)
    async def store_artifact_endpoint(
        file: UploadFile = File(...),
        location: Optional[str] = Form(None),
        location_key: Optional[str] = Form(None),
        path: Optional[str] = Form(None),
        filename: Optional[str] = Form(None),
    ) -> Response:
        # Accept either 'location' or 'location_key' as aliases
        effective_location = location_key or location
        if path and (effective_location or filename):
            return _error_response(
                400,
                "validation_error",
                "Provide either 'path' or 'location'+'filename', not both",
                {},
            )
        if not path and not (effective_location and filename):
            return _error_response(
                400,
                "validation_error",
                "Missing target path: provide 'path' or 'location' and 'filename'",
                {},
            )
        try:
            file_bytes = await file.read()
        except Exception as exc:
            logger.exception("Failed to read uploaded file")
            return _error_response(
                400,
                "file_read_error",
                "Failed to read uploaded file",
                {"detail": str(exc)},
            )
        try:
            if path:
                artifact_id = store_artifact(file_bytes=file_bytes, location_key=path, filename=None)
            else:
                artifact_id = store_artifact(
                    file_bytes=file_bytes, location_key=effective_location or "", filename=filename
                )
            metadata = get_artifact_metadata(artifact_id)
        except InvalidArtifactExtensionError as exc:
            logger.warning("Rejected artifact due to extension: %s", exc)
            return _error_response(
                422,
                "extension_not_allowed",
                str(exc),
                {},
            )
        except InvalidArtifactPathError as exc:
            logger.warning("Rejected artifact due to invalid path: %s", exc)
            return _error_response(
                422,
                "path_not_allowed",
                str(exc),
                {},
            )
        except ArtifactConflictError as exc:
            return _error_response(
                409,
                "conflict",
                str(exc),
                {},
            )
        except StorageError as exc:
            return _error_response(
                500,
                "storage_error",
                "Failed to store artifact",
                {"detail": str(exc)},
            )
        return JSONResponse(status_code=201, content={
            "artifact_id": artifact_id,
            "path": metadata["path"],
            "domain": metadata["domain"],
        })

    @app.get("/artifact/{artifact_id:path}/content")
    async def get_artifact_content_endpoint(
        artifact_id: str = ApiPath(..., description="Artifact ID (relative path)"),
    ) -> Response:
        try:
            file_path = get_artifact_content_path(artifact_id)
        except ArtifactNotFoundError:
            return _error_response(
                404,
                "not_found",
                "Artifact not found",
                {"artifact_id": artifact_id},
            )
        except InvalidArtifactExtensionError as exc:
            return _error_response(
                422,
                "extension_not_allowed",
                str(exc),
                {"artifact_id": artifact_id},
            )
        except InvalidArtifactPathError as exc:
            return _error_response(
                422,
                "path_not_allowed",
                str(exc),
                {"artifact_id": artifact_id},
            )
        # Use FileResponse to stream the file without loading into memory
        return FileResponse(
            path=str(file_path),
            media_type="application/octet-stream",
            filename=file_path.name
        )

    @app.get("/artifact/{artifact_id:path}")
    async def get_artifact_metadata_endpoint(
        artifact_id: str = ApiPath(..., description="Artifact ID (relative path)"),
    ) -> Response:
        try:
            metadata = get_artifact_metadata(artifact_id)
        except ArtifactNotFoundError:
            return _error_response(
                404,
                "not_found",
                "Artifact not found",
                {"artifact_id": artifact_id},
            )
        except InvalidArtifactExtensionError as exc:
            return _error_response(
                422,
                "extension_not_allowed",
                str(exc),
                {"artifact_id": artifact_id},
            )
        except InvalidArtifactPathError as exc:
            return _error_response(
                422,
                "path_not_allowed",
                str(exc),
                {"artifact_id": artifact_id},
            )
        return JSONResponse(content=metadata)

    @app.post("/artifact/search")
    async def search_artifacts_endpoint(payload: SearchRequest) -> Response:
        try:
            result = search_artifacts(payload.dict(exclude_none=True))
        except InvalidArtifactPathError as exc:
            return _error_response(
                400,
                "validation_error",
                str(exc),
                {},
            )
        return JSONResponse(content=result)

    @app.get("/registry/locations")
    async def get_registry_locations_endpoint() -> Response:
        try:
            locations = list_all_locations()
        except RegistryError as exc:
            return _error_response(
                500,
                "registry_error",
                "Failed to load registry",
                {"detail": str(exc)},
            )
        return JSONResponse(content={"locations": locations})

    @app.post("/registry/validate")
    async def validate_registry_endpoint(
        payload: RegistryValidateRequest,
    ) -> Response:
        errors = validate_registry(payload.locations)
        return JSONResponse(content={
            "valid": not errors,
            "errors": [e.to_dict() for e in errors],
        })

    return app


app = create_app()

from __future__ import annotations

import json
import logging
import os
import tempfile
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from typing import Any, Dict, List, Optional

from . import get_artifacts_root
from .filename_parsing import extract_fields, tokenize_filename
from .registry import (
    LocationEntry,
    LocationNotFoundError,
    RegistryNotLoadedError,
    match_location,
)

logger = logging.getLogger(__name__)


class StorageError(Exception):
    """Base class for storage-layer errors."""


class ArtifactNotFoundError(StorageError):
    """Raised when an artifact cannot be located on disk."""


class InvalidArtifactPathError(StorageError):
    """Raised when an artifact path is invalid or escapes the root."""


class ArtifactConflictError(StorageError):
    """Raised when attempting to overwrite an existing artifact."""


class InvalidArtifactExtensionError(StorageError):
    """Raised when an artifact has an extension not allowed by the registry."""


def _normalize_relative_path(location_key: str, filename: Optional[str]) -> PurePosixPath:
    # Build the raw path string first
    if filename is None or filename == "":
        raw_path = location_key
    else:
        raw_path = f"{location_key}/{filename}"

    # Check raw path segments before PurePosixPath normalizes them away
    raw_parts = raw_path.split("/")
    for part in raw_parts:
        if part in (".", ".."):
            logger.warning(
                "Rejecting artifact path with special segment '%s': %s",
                part,
                raw_path,
            )
            raise InvalidArtifactPathError(
                f"Path must not contain special segments ('.' or '..')"
            )

    # Now create the PurePosixPath (will normalize empty segments)
    rel = PurePosixPath(raw_path)
    parts: List[str] = []
    for part in rel.parts:
        if part == "":
            continue
        parts.append(part)
    if not parts:
        raise InvalidArtifactPathError("Artifact path must not be empty")
    return PurePosixPath(*parts)


def _artifact_path_from_id(artifact_id: str) -> Path:
    rel = PurePosixPath(artifact_id)
    if any(part in ("", ".", "..") for part in rel.parts):
        raise InvalidArtifactPathError("Artifact ID contains invalid path segments")
    root = get_artifacts_root()
    return root.joinpath(*rel.parts)


def _infer_location_entry_for_relative_path(rel_path: PurePosixPath) -> LocationEntry:
    return match_location(list(rel_path.parts))


def _validate_extension_for_location(
    filename: str, location: LocationEntry
) -> str:
    name = Path(filename).name
    suffix = Path(name).suffix
    if not suffix:
        raise InvalidArtifactExtensionError(
            f"Artifact '{name}' must have an extension allowed by the registry"
        )
    ext_lower = suffix.lower()
    allowed = {e.lower() for e in location.allowed_extensions}
    if ext_lower not in allowed:
        raise InvalidArtifactExtensionError(
            f"Extension '{suffix}' is not allowed for location '{location.key}'"
        )
    return suffix


def _atomic_write(target: Path, content: bytes) -> None:
    target.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        dir=str(target.parent), delete=False
    ) as tmp:
        try:
            tmp.write(content)
            tmp.flush()
            os.fsync(tmp.fileno())
        except OSError:
            try:
                os.unlink(tmp.name)
            except OSError:
                logger.exception("Failed to clean up temporary file %s", tmp.name)
            raise
        tmp_path = Path(tmp.name)
    # Atomic rename that fails if target exists (POSIX-only)
    try:
        os.link(tmp_path, target)
        os.unlink(tmp_path)
    except FileExistsError as exc:
        os.unlink(tmp_path)
        raise ArtifactConflictError(f"Artifact already exists at {target}") from exc
    except OSError as exc:
        # On non-POSIX or cross-filesystem, fall back to replace with prior check
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise StorageError(f"Failed to atomically write artifact: {exc}") from exc


def _load_custom_metadata(path: Path) -> Optional[Dict[str, Any]]:
    meta_path = Path(str(path) + ".metadata.json")
    if not meta_path.is_file():
        return None
    try:
        text = meta_path.read_text(encoding="utf-8")
        data = json.loads(text)
        if isinstance(data, dict):
            return data
        return {"value": data}
    except (OSError, json.JSONDecodeError):
        logger.exception("Failed to read metadata override from %s", meta_path)
        return None


def store_artifact(
    file_bytes: bytes, location_key: str, filename: Optional[str] = None
) -> str:
    """Store an artifact under the managed root and return its artifact ID."""

    rel_path = _normalize_relative_path(location_key, filename)
    try:
        location_entry = _infer_location_entry_for_relative_path(rel_path)
    except LocationNotFoundError as exc:
        logger.warning("Rejecting artifact for unknown location: %s", rel_path)
        raise InvalidArtifactPathError(str(exc)) from exc
    _ = _validate_extension_for_location(rel_path.name, location_entry)
    root = get_artifacts_root()
    target = root.joinpath(*rel_path.parts)
    try:
        _atomic_write(target, file_bytes)
    except ArtifactConflictError:
        logger.info("Artifact conflict at %s", target)
        raise
    except OSError as exc:
        logger.exception("Filesystem error while writing artifact to %s", target)
        raise StorageError(f"Failed to write artifact: {exc}") from exc
    artifact_id = rel_path.as_posix()
    return artifact_id


def get_artifact_content_path(artifact_id: str) -> Path:
    """Return the filesystem path for an artifact's content.

    The caller is responsible for opening and reading the file.
    Use this for streaming large files without loading into memory.

    Validates that the artifact is registered and has an allowed extension.
    """
    path = _artifact_path_from_id(artifact_id)
    if not path.is_file():
        raise ArtifactNotFoundError(f"Artifact not found at {artifact_id}")

    # Validate registry coverage and extension (same as get_artifact_metadata)
    rel_path = PurePosixPath(artifact_id)
    try:
        location_entry = _infer_location_entry_for_relative_path(rel_path)
    except LocationNotFoundError as exc:
        raise InvalidArtifactPathError(str(exc)) from exc

    # Validate extension is allowed
    _ = _validate_extension_for_location(path.name, location_entry)

    # Optional: block .metadata.json files from being served as artifacts
    if path.name.endswith(".metadata.json"):
        raise InvalidArtifactPathError("Metadata files cannot be retrieved as artifacts")

    return path


def get_artifact_content(artifact_id: str) -> bytes:
    """Return the raw bytes content for an artifact.

    WARNING: This loads the entire file into memory. For large files,
    use get_artifact_content_path() and stream instead.
    """
    path = get_artifact_content_path(artifact_id)
    try:
        return path.read_bytes()
    except OSError as exc:
        logger.exception("Failed to read artifact content from %s", path)
        raise StorageError(f"Failed to read artifact: {exc}") from exc


def get_artifact_metadata(artifact_id: str) -> Dict[str, Any]:
    """Infer metadata for an artifact from its path and registry entry."""

    path = _artifact_path_from_id(artifact_id)
    if not path.is_file():
        raise ArtifactNotFoundError(f"Artifact not found at {artifact_id}")
    rel_path = PurePosixPath(artifact_id)
    try:
        location_entry = _infer_location_entry_for_relative_path(rel_path)
    except LocationNotFoundError as exc:
        raise InvalidArtifactPathError(str(exc)) from exc
    extension = Path(path.name).suffix
    _ = _validate_extension_for_location(path.name, location_entry)
    rules_dict: Optional[Dict[str, Any]] = None
    if location_entry.filename_rules is not None:
        rules = location_entry.filename_rules
        rules_dict = {
            "token_delimiters": rules.token_delimiters,
            "case": rules.case,
        }
    tokens = tokenize_filename(path.name, rules=rules_dict)
    pattern_defs = None
    if location_entry.filename_rules is not None:
        pattern_defs = [
            {"name": p.name, "regex": p.regex}
            for p in location_entry.filename_rules.patterns
        ]
    fields = extract_fields(path.name, patterns=pattern_defs)
    metadata: Dict[str, Any] = {
        "artifact_id": artifact_id,
        "path": rel_path.as_posix(),
        "domain": location_entry.domain,
        "location": location_entry.key,
        "tags": list(location_entry.tags),
        "topics": list(location_entry.topics),
        "filename": path.name,
        "extension": extension,
        "tokens": tokens,
        "fields": fields,
    }
    custom = _load_custom_metadata(path)
    if custom is not None:
        metadata["custom"] = custom
    return metadata


def list_artifacts(location_prefix: str) -> List[str]:
    """List all artifact IDs under a given location prefix."""

    # Reject absolute paths or paths that escape the root
    if location_prefix.startswith("/"):
        raise InvalidArtifactPathError("Location prefix must not be an absolute path")

    rel_prefix = PurePosixPath(location_prefix)
    if any(part in ("", ".", "..") for part in rel_prefix.parts):
        raise InvalidArtifactPathError("Location prefix contains invalid segments")

    root = get_artifacts_root()
    base = root.joinpath(*rel_prefix.parts)

    # Verify base is within the artifact root
    try:
        base.resolve().relative_to(root.resolve())
    except ValueError as exc:
        raise InvalidArtifactPathError("Location prefix escapes artifact root") from exc
    if not base.exists():
        return []
    artifact_ids: List[str] = []
    for path in base.rglob("*"):
        if not path.is_file():
            continue
        # Skip metadata override files - they are not artifacts themselves
        if path.name.endswith(".metadata.json"):
            continue
        rel = path.relative_to(root)
        rel_posix = rel.as_posix()
        try:
            location_entry = _infer_location_entry_for_relative_path(
                PurePosixPath(rel_posix)
            )
        except LocationNotFoundError:
            continue
        ext_lower = path.suffix.lower()
        allowed = {e.lower() for e in location_entry.allowed_extensions}
        if ext_lower not in allowed:
            continue
        artifact_ids.append(rel_posix)
    return artifact_ids

from __future__ import annotations

import json
import logging
import re
import threading
from dataclasses import dataclass, field, asdict
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

from . import get_registry_path

logger = logging.getLogger(__name__)


@dataclass
class ValidationError:
    path: str
    error: str
    details: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        data: Dict[str, Any] = {"path": self.path, "error": self.error}
        if self.details:
            data["details"] = self.details
        return data


class RegistryError(Exception):
    """Base class for registry-related failures."""


class RegistryNotLoadedError(RegistryError):
    """Raised when registry-backed operations are used before load."""


class RegistryValidationException(RegistryError):
    """Raised when the registry has structural validation errors."""

    def __init__(self, errors: Sequence[ValidationError]):
        self.errors = list(errors)
        message = "Registry validation failed"
        if errors:
            first = errors[0]
            message = f"{message}: {first.path}: {first.error}"
        super().__init__(message)


class LocationNotFoundError(RegistryError):
    """Raised when no registry location matches a given path."""

    def __init__(self, path_parts: Sequence[str]):
        self.path_parts = list(path_parts)
        super().__init__(f"No registry location matches path: {'/'.join(path_parts)}")


@dataclass
class FilenamePattern:
    name: str
    regex: str


@dataclass
class FilenameRules:
    token_delimiters: List[str] = field(default_factory=lambda: ["_", "-", " "])
    case: str = "lower"
    patterns: List[FilenamePattern] = field(default_factory=list)


@dataclass
class LocationEntry:
    key: str
    domain: str
    tags: List[str]
    topics: List[str]
    allowed_extensions: List[str]
    filename_rules: Optional[FilenameRules] = None

    def to_serializable(self) -> Dict[str, Any]:
        data = asdict(self)
        data.pop("key", None)
        if self.filename_rules is None:
            data.pop("filename_rules", None)
        else:
            rules = self.filename_rules
            rules_dict: Dict[str, Any] = {
                "token_delimiters": rules.token_delimiters,
                "case": rules.case,
                "patterns": [
                    {"name": p.name, "regex": p.regex} for p in rules.patterns
                ],
            }
            data["filename_rules"] = rules_dict
        return data


_REGISTRY: Dict[str, LocationEntry] = {}
_REGISTRY_LOCK = threading.Lock()


def _validate_location_key(key: Any, errors: List[ValidationError]) -> Optional[str]:
    if not isinstance(key, str):
        errors.append(
            ValidationError(
                path="locations",
                error="location key must be a string",
                details={"key": key},
            )
        )
        return None
    if not key:
        errors.append(
            ValidationError(
                path="locations",
                error="location key must not be empty",
                details={"key": key},
            )
        )
        return None
    if key.startswith("/") or key.endswith("/"):
        errors.append(
            ValidationError(
                path=f"locations.{key}",
                error="location key must be relative without leading or trailing slash",
            )
        )
    if "//" in key:
        errors.append(
            ValidationError(
                path=f"locations.{key}",
                error="location key must not contain empty path segments",
            )
        )
    parts = key.split("/")
    if any(part in ("", ".", "..") for part in parts):
        errors.append(
            ValidationError(
                path=f"locations.{key}",
                error="location key must not contain '.' or '..' segments",
            )
        )
    return key


def _validate_required_string_field(
    container_path: str,
    name: str,
    value: Any,
    errors: List[ValidationError],
) -> Optional[str]:
    if not isinstance(value, str) or not value:
        errors.append(
            ValidationError(
                path=f"{container_path}.{name}",
                error="must be a non-empty string",
            )
        )
        return None
    return value


def _validate_string_list_field(
    container_path: str,
    name: str,
    value: Any,
    errors: List[ValidationError],
    require_non_empty: bool = True,
) -> Optional[List[str]]:
    if not isinstance(value, list):
        errors.append(
            ValidationError(
                path=f"{container_path}.{name}",
                error="must be a list of strings",
            )
        )
        return None
    if require_non_empty and not value:
        errors.append(
            ValidationError(
                path=f"{container_path}.{name}",
                error="must not be empty",
            )
        )
        return None
    result: List[str] = []
    for idx, item in enumerate(value):
        if not isinstance(item, str) or not item:
            errors.append(
                ValidationError(
                    path=f"{container_path}.{name}[{idx}]",
                    error="must be a non-empty string",
                )
            )
        else:
            result.append(item)
    return result


def _validate_allowed_extensions(
    container_path: str,
    value: Any,
    errors: List[ValidationError],
) -> Optional[List[str]]:
    exts = _validate_string_list_field(
        container_path, "allowed_extensions", value, errors, require_non_empty=True
    )
    if exts is None:
        return None
    normalized: List[str] = []
    for idx, ext in enumerate(exts):
        if not ext.startswith(".") or len(ext) < 2:
            errors.append(
                ValidationError(
                    path=f"{container_path}.allowed_extensions[{idx}]",
                    error="extension must start with '.' and have at least one character after",
                    details={"value": ext},
                )
            )
        else:
            normalized.append(ext)
    if not normalized:
        errors.append(
            ValidationError(
                path=f"{container_path}.allowed_extensions",
                error="must contain at least one valid extension",
            )
        )
        return None
    return normalized


def _validate_filename_rules(
    container_path: str, value: Any, errors: List[ValidationError]
) -> Optional[FilenameRules]:
    if value is None:
        return None
    if not isinstance(value, dict):
        errors.append(
            ValidationError(
                path=f"{container_path}.filename_rules",
                error="must be an object",
            )
        )
        return None
    allowed_fields = {"token_delimiters", "case", "patterns"}
    for field_name in value.keys():
        if field_name not in allowed_fields:
            errors.append(
                ValidationError(
                    path=f"{container_path}.filename_rules.{field_name}",
                    error="unknown field",
                )
            )
    token_delimiters: Optional[List[str]] = None
    if "token_delimiters" in value:
        token_delimiters = _validate_string_list_field(
            f"{container_path}.filename_rules",
            "token_delimiters",
            value.get("token_delimiters"),
            errors,
            require_non_empty=True,
        )
    case_value: str = "lower"
    if "case" in value:
        raw_case = value.get("case")
        if raw_case not in ("lower", "preserve"):
            errors.append(
                ValidationError(
                    path=f"{container_path}.filename_rules.case",
                    error='must be "lower" or "preserve"',
                    details={"value": raw_case},
                )
            )
        else:
            case_value = str(raw_case)
    patterns_value: List[FilenamePattern] = []
    if "patterns" in value:
        patterns_raw = value.get("patterns")
        if not isinstance(patterns_raw, list):
            errors.append(
                ValidationError(
                    path=f"{container_path}.filename_rules.patterns",
                    error="must be a list of pattern objects",
                )
            )
        else:
            for idx, pattern in enumerate(patterns_raw):
                pattern_path = f"{container_path}.filename_rules.patterns[{idx}]"
                if not isinstance(pattern, dict):
                    errors.append(
                        ValidationError(
                            path=pattern_path,
                            error="must be an object",
                        )
                    )
                    continue
                name = pattern.get("name")
                regex = pattern.get("regex")
                if not isinstance(name, str) or not name:
                    errors.append(
                        ValidationError(
                            path=f"{pattern_path}.name",
                            error="must be a non-empty string",
                        )
                    )
                    continue
                if not isinstance(regex, str) or not regex:
                    errors.append(
                        ValidationError(
                            path=f"{pattern_path}.regex",
                            error="must be a non-empty string",
                        )
                    )
                    continue
                try:
                    re.compile(regex)
                except re.error as exc:
                    errors.append(
                        ValidationError(
                            path=f"{pattern_path}.regex",
                            error="invalid regular expression",
                            details={"message": str(exc)},
                        )
                    )
                    continue
                patterns_value.append(FilenamePattern(name=name, regex=regex))
    if errors:
        return None
    rules = FilenameRules()
    if token_delimiters is not None:
        rules.token_delimiters = token_delimiters
    rules.case = case_value
    rules.patterns = patterns_value
    return rules


def validate_registry(data: Any) -> List[ValidationError]:
    """Validate a raw registry object loaded from JSON."""

    errors: List[ValidationError] = []
    if not isinstance(data, dict):
        errors.append(
            ValidationError(
                path="locations",
                error="registry root must be an object mapping location keys to definitions",
            )
        )
        return errors

    # Validate individual entries and collect valid keys
    valid_keys: List[str] = []
    for raw_key, raw_value in data.items():
        key = _validate_location_key(raw_key, errors)
        if key is None:
            continue
        valid_keys.append(key)
        container_path = f"locations.{key}"
        if not isinstance(raw_value, dict):
            errors.append(
                ValidationError(
                    path=container_path,
                    error="location definition must be an object",
                )
            )
            continue
        allowed_fields = {
            "domain",
            "tags",
            "topics",
            "allowed_extensions",
            "filename_rules",
        }
        for field_name in raw_value.keys():
            if field_name not in allowed_fields:
                errors.append(
                    ValidationError(
                        path=f"{container_path}.{field_name}",
                        error="unknown field",
                    )
                )
        domain = _validate_required_string_field(
            container_path, "domain", raw_value.get("domain"), errors
        )
        _ = _validate_string_list_field(
            container_path, "tags", raw_value.get("tags"), errors, require_non_empty=True
        )
        _ = _validate_string_list_field(
            container_path,
            "topics",
            raw_value.get("topics"),
            errors,
            require_non_empty=True,
        )
        _ = _validate_allowed_extensions(
            container_path, raw_value.get("allowed_extensions"), errors
        )
        _ = _validate_filename_rules(
            container_path, raw_value.get("filename_rules"), errors
        )
        if domain is None:
            continue

    # Check for exact duplicate keys
    # NOTE: Overlapping prefixes (e.g., "cnc" and "cnc/design") are INTENTIONAL
    # and required for longest-prefix matching per registry_design.md:134
    # We only flag exact duplicates here.
    seen_keys: set[str] = set()
    for key in valid_keys:
        if key in seen_keys:
            errors.append(
                ValidationError(
                    path=f"locations.{key}",
                    error="duplicate location key",
                )
            )
        seen_keys.add(key)

    return errors


def _materialize_location_entry(
    key: str, definition: Dict[str, Any]
) -> LocationEntry:
    container_path = f"locations.{key}"
    errors: List[ValidationError] = []
    domain = str(definition["domain"])
    tags = [str(t) for t in definition["tags"]]
    topics = [str(t) for t in definition["topics"]]
    allowed_extensions = [str(e) for e in definition["allowed_extensions"]]
    filename_rules = _validate_filename_rules(
        container_path, definition.get("filename_rules"), errors
    )
    if errors:
        raise RegistryValidationException(errors)
    return LocationEntry(
        key=key,
        domain=domain,
        tags=tags,
        topics=topics,
        allowed_extensions=allowed_extensions,
        filename_rules=filename_rules,
    )


def load_registry(path: str | Path | None = None) -> Dict[str, LocationEntry]:
    """Load and validate the registry from the given path."""

    registry_path = Path(path) if path is not None else get_registry_path()
    try:
        raw_text = registry_path.read_text(encoding="utf-8")
    except FileNotFoundError as exc:
        raise RegistryError(f"Registry file not found at {registry_path}") from exc
    try:
        raw_data = json.loads(raw_text)
    except json.JSONDecodeError as exc:
        raise RegistryError(f"Failed to parse registry JSON: {exc}") from exc
    errors = validate_registry(raw_data)
    if errors:
        logger.error("Registry validation failed with %d error(s):", len(errors))
        for error in errors:
            logger.error("  %s: %s", error.path, error.error)
            if error.details:
                logger.error("    Details: %s", error.details)
        raise RegistryValidationException(errors)
    registry: Dict[str, LocationEntry] = {}
    for key, value in raw_data.items():
        if not isinstance(value, dict):
            continue
        entry = _materialize_location_entry(str(key), value)
        registry[entry.key] = entry
    global _REGISTRY
    with _REGISTRY_LOCK:
        _REGISTRY = registry
        logger.info("Loaded registry with %d locations from %s", len(_REGISTRY), registry_path)
        return dict(_REGISTRY)


def _ensure_loaded() -> None:
    with _REGISTRY_LOCK:
        if not _REGISTRY:
            raise RegistryNotLoadedError("Registry has not been loaded")


def match_location(path_parts: List[str]) -> LocationEntry:
    """Return the registry location entry that best matches a path."""

    _ensure_loaded()
    segments = [p for p in path_parts if p not in ("", ".")]
    if not segments:
        raise LocationNotFoundError(path_parts)
    best_key: Optional[str] = None
    best_entry: Optional[LocationEntry] = None
    with _REGISTRY_LOCK:
        for key, entry in _REGISTRY.items():
            key_parts = key.split("/")
            if len(key_parts) > len(segments):
                continue
            if segments[: len(key_parts)] != key_parts:
                continue
            if best_key is None or len(key_parts) > len(best_key.split("/")):
                best_key = key
                best_entry = entry
    if best_entry is None:
        raise LocationNotFoundError(path_parts)
    return best_entry


def get_location_metadata(location_key: str) -> LocationEntry:
    """Return the location entry for a specific location key."""

    _ensure_loaded()
    with _REGISTRY_LOCK:
        try:
            return _REGISTRY[location_key]
        except KeyError as exc:
            raise LocationNotFoundError([location_key]) from exc


def list_all_locations() -> Dict[str, Dict[str, Any]]:
    """Return a serializable view of all registry locations."""

    _ensure_loaded()
    with _REGISTRY_LOCK:
        return {key: entry.to_serializable() for key, entry in _REGISTRY.items()}


def get_registry_entries() -> Dict[str, LocationEntry]:
    """Return the internal registry mapping."""

    _ensure_loaded()
    with _REGISTRY_LOCK:
        return dict(_REGISTRY)

from __future__ import annotations

import logging
from pathlib import Path, PurePosixPath
from typing import Any, Dict, Iterable, List, Optional, Tuple

from . import get_artifacts_root
from .filename_parsing import tokenize_filename
from .registry import LocationEntry, LocationNotFoundError, get_registry_entries, match_location
from .storage import (
    ArtifactNotFoundError,
    InvalidArtifactExtensionError,
    InvalidArtifactPathError,
    get_artifact_metadata,
)

logger = logging.getLogger(__name__)


def _enumerate_candidate_files() -> List[Tuple[str, LocationEntry, Path]]:
    root = get_artifacts_root()
    registry = get_registry_entries()
    candidates: List[Tuple[str, LocationEntry, Path]] = []
    seen: set[str] = set()
    if not root.exists():
        return []
    for path in root.rglob("*"):
        if not path.is_file():
            continue
        # Skip metadata override files - they are not artifacts themselves
        if path.name.endswith(".metadata.json"):
            continue
        rel = path.relative_to(root)
        artifact_id = rel.as_posix()
        if artifact_id in seen:
            continue
        seen.add(artifact_id)
        rel_posix = PurePosixPath(artifact_id)
        try:
            location_entry = match_location(list(rel_posix.parts))
        except LocationNotFoundError:
            continue
        suffix = path.suffix.lower()
        allowed = {e.lower() for e in location_entry.allowed_extensions}
        if suffix not in allowed:
            continue
        candidates.append((artifact_id, location_entry, path))
    return candidates


def search_artifacts(criteria: Dict[str, Any]) -> Dict[str, Any]:
    """Search artifacts using the elimination pipeline."""

    domains_filter = set(criteria.get("domains") or [])
    locations_filter = set(criteria.get("locations") or [])
    tags_filter = set(criteria.get("tags") or [])
    topics_filter = set(criteria.get("topics") or [])
    keywords_raw = criteria.get("keywords") or []
    keywords_filter = {str(k) for k in keywords_raw}
    limit_raw = criteria.get("limit", 50)
    offset_raw = criteria.get("offset", 0)
    try:
        limit = int(limit_raw)
        offset = int(offset_raw)
    except (TypeError, ValueError) as exc:
        raise InvalidArtifactPathError("limit and offset must be integers") from exc
    if limit <= 0:
        raise InvalidArtifactPathError("limit must be positive")
    if offset < 0:
        raise InvalidArtifactPathError("offset must be non-negative")
    candidates = _enumerate_candidate_files()
    total_candidates = len(candidates)
    after_domain_list: List[Tuple[str, LocationEntry, Path]] = []
    for artifact_id, location_entry, path in candidates:
        if domains_filter and location_entry.domain not in domains_filter:
            continue
        after_domain_list.append((artifact_id, location_entry, path))
    after_domain = len(after_domain_list)
    after_location_list: List[Tuple[str, LocationEntry, Path]] = []
    for artifact_id, location_entry, path in after_domain_list:
        if locations_filter:
            loc_key = location_entry.key
            matched = False
            for prefix in locations_filter:
                if loc_key == prefix or loc_key.startswith(prefix + "/"):
                    matched = True
                    break
            if not matched:
                continue
        after_location_list.append((artifact_id, location_entry, path))
    after_location = len(after_location_list)
    after_tags_topics_list: List[Tuple[str, LocationEntry, Path]] = []
    for artifact_id, location_entry, path in after_location_list:
        if tags_filter:
            if not tags_filter.issubset(set(location_entry.tags)):
                continue
        if topics_filter:
            if not topics_filter.issubset(set(location_entry.topics)):
                continue
        after_tags_topics_list.append((artifact_id, location_entry, path))
    after_tags_topics = len(after_tags_topics_list)
    surviving: List[Tuple[str, LocationEntry, Path]] = []
    for artifact_id, location_entry, path in after_tags_topics_list:
        if keywords_filter:
            rules_dict: Optional[Dict[str, Any]] = None
            if location_entry.filename_rules is not None:
                rules = location_entry.filename_rules
                rules_dict = {
                    "token_delimiters": rules.token_delimiters,
                    "case": rules.case,
                }
            tokens = tokenize_filename(path.name, rules=rules_dict)
            # Normalize both tokens and keywords based on location's case setting
            normalize_case = rules_dict.get("case", "lower") if rules_dict else "lower"
            if normalize_case == "lower":
                token_set = {t.lower() for t in tokens}
                normalized_keywords = {k.lower() for k in keywords_filter}
            else:
                token_set = set(tokens)
                normalized_keywords = keywords_filter
            if not normalized_keywords.issubset(token_set):
                continue
        surviving.append((artifact_id, location_entry, path))
    after_keywords = len(surviving)
    surviving.sort(
        key=lambda item: (
            item[1].domain,
            item[1].key,
            item[0],
            Path(item[0]).name,
        )
    )
    sliced = surviving[offset : offset + limit]
    results: List[Dict[str, Any]] = []
    for artifact_id, _location_entry, _path in sliced:
        try:
            metadata = get_artifact_metadata(artifact_id)
        except (ArtifactNotFoundError, InvalidArtifactExtensionError) as exc:
            logger.warning("Skipping artifact %s during search: %s", artifact_id, exc)
            continue
        results.append(metadata)
    elimination_trace = {
        "total_candidates": total_candidates,
        "after_domain": after_domain,
        "after_location": after_location,
        "after_tags_topics": after_tags_topics,
        "after_keywords": after_keywords,
    }
    return {"results": results, "elimination_trace": elimination_trace}

from __future__ import annotations

import re
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional


def _strip_extension(filename: str) -> str:
    name = Path(filename).name
    if "." not in name:
        return name
    return name.rsplit(".", 1)[0]


def _apply_camel_case_boundaries(text: str) -> str:
    pattern = re.compile(r"(?<=[a-z0-9])(?=[A-Z])")
    return pattern.sub(" ", text)


def tokenize_filename(filename: str, rules: Optional[Dict[str, Any]] = None) -> List[str]:
    """Tokenize a filename into normalized tokens based on rules."""

    base = _strip_extension(filename)
    base = _apply_camel_case_boundaries(base)
    token_delimiters: List[str]
    normalize_case = "lower"
    if rules is not None:
        token_delimiters = rules.get("token_delimiters") or ["_", "-", " "]
        normalize_case = rules.get("case") or "lower"
    else:
        token_delimiters = ["_", "-", " "]
    pattern = "|".join(re.escape(d) for d in token_delimiters)
    if not pattern:
        raw_tokens = [base]
    else:
        raw_tokens = re.split(pattern, base)
    tokens = [t.strip() for t in raw_tokens if t and t.strip()]
    if normalize_case == "lower":
        tokens = [t.lower() for t in tokens]
    return tokens


def extract_fields(
    filename: str, patterns: Optional[Iterable[Dict[str, Any]]] = None
) -> Dict[str, str]:
    """Extract structured fields from a filename using regex patterns."""

    if patterns is None:
        return {}
    base = _strip_extension(filename)
    fields: Dict[str, str] = {}
    for pattern in patterns:
        name = pattern.get("name")
        regex = pattern.get("regex")
        if not isinstance(name, str) or not isinstance(regex, str):
            continue
        if name in fields:
            continue
        try:
            compiled = re.compile(regex)
        except re.error:
            continue
        match = compiled.search(base)
        if match:
            fields[name] = match.group(0)
    return fields

from __future__ import annotations

import argparse
import json
import sys
from typing import Any, Dict, List

from artifact_manager.registry import RegistryError, load_registry
from artifact_manager.search import search_artifacts
from artifact_manager.storage import (
    ArtifactNotFoundError,
    InvalidArtifactPathError,
    get_artifact_content,
    get_artifact_metadata,
    list_artifacts,
)


def _print_json(data: Any) -> None:
    json.dump(data, sys.stdout, indent=2, sort_keys=True)
    sys.stdout.write("\n")


def cmd_list(args: argparse.Namespace) -> int:
    try:
        ids = list_artifacts(args.location)
    except InvalidArtifactPathError as exc:
        sys.stderr.write(f"Error: {exc}\n")
        return 1
    for artifact_id in ids:
        sys.stdout.write(f"{artifact_id}\n")
    return 0


def cmd_search(args: argparse.Namespace) -> int:
    criteria: Dict[str, Any] = {}
    if args.domain:
        criteria["domains"] = args.domain
    if args.location:
        criteria["locations"] = args.location
    tags: List[str] = []
    if args.tag:
        tags.extend(args.tag)
    if args.type:
        tags.extend(args.type)
    if tags:
        criteria["tags"] = tags
    if args.topic:
        criteria["topics"] = args.topic
    if args.keywords:
        keywords = [k.strip() for k in args.keywords.split(",") if k.strip()]
        if keywords:
            criteria["keywords"] = keywords
    criteria["limit"] = args.limit
    criteria["offset"] = args.offset
    try:
        result = search_artifacts(criteria)
    except InvalidArtifactPathError as exc:
        sys.stderr.write(f"Error: {exc}\n")
        return 1
    if args.json:
        _print_json(result)
    else:
        for item in result.get("results", []):
            sys.stdout.write(f"{item.get('artifact_id')}\n")
    return 0


def cmd_show(args: argparse.Namespace) -> int:
    try:
        metadata = get_artifact_metadata(args.artifact_id)
    except ArtifactNotFoundError:
        sys.stderr.write("Error: artifact not found\n")
        return 1
    except InvalidArtifactPathError as exc:
        sys.stderr.write(f"Error: {exc}\n")
        return 1
    _print_json(metadata)
    return 0


def cmd_content(args: argparse.Namespace) -> int:
    try:
        content = get_artifact_content(args.artifact_id)
    except ArtifactNotFoundError:
        sys.stderr.write("Error: artifact not found\n")
        return 1
    except InvalidArtifactPathError as exc:
        sys.stderr.write(f"Error: {exc}\n")
        return 1
    sys.stdout.buffer.write(content)
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="artifact", description="Artifact Engine CLI")
    subparsers = parser.add_subparsers(dest="command", required=True)
    list_parser = subparsers.add_parser("list", help="List artifacts under a location")
    list_parser.add_argument("location", help="Location prefix, for example 'cnc/design'")
    list_parser.set_defaults(func=cmd_list)
    search_parser = subparsers.add_parser("search", help="Search for artifacts")
    search_parser.add_argument(
        "--domain",
        "-d",
        action="append",
        help="Domain filter (can be repeated)",
    )
    search_parser.add_argument(
        "--location",
        "-l",
        action="append",
        help="Location prefix filter (can be repeated)",
    )
    search_parser.add_argument(
        "--tag",
        action="append",
        help="Tag filter (can be repeated)",
    )
    search_parser.add_argument(
        "--type",
        action="append",
        help="Alias for --tag",
    )
    search_parser.add_argument(
        "--topic",
        action="append",
        help="Topic filter (can be repeated)",
    )
    search_parser.add_argument(
        "--keywords",
        "-k",
        help="Comma-separated list of keywords",
    )
    search_parser.add_argument(
        "--limit",
        type=int,
        default=50,
        help="Maximum number of results to return",
    )
    search_parser.add_argument(
        "--offset",
        type=int,
        default=0,
        help="Offset into the result set",
    )
    search_parser.add_argument(
        "--json",
        action="store_true",
        help="Output full JSON results",
    )
    search_parser.set_defaults(func=cmd_search)
    show_parser = subparsers.add_parser(
        "show", help="Show inferred metadata for an artifact"
    )
    show_parser.add_argument("artifact_id", help="Artifact ID (relative path)")
    show_parser.set_defaults(func=cmd_show)
    content_parser = subparsers.add_parser(
        "content", help="Stream artifact content to stdout"
    )
    content_parser.add_argument("artifact_id", help="Artifact ID (relative path)")
    content_parser.set_defaults(func=cmd_content)
    return parser


def main(argv: List[str] | None = None) -> int:
    try:
        load_registry()
    except RegistryError as exc:
        sys.stderr.write(f"Failed to load registry: {exc}\n")
        return 1
    parser = build_parser()
    args = parser.parse_args(argv)
    func = getattr(args, "func", None)
    if func is None:
        parser.print_help()
        return 1
    return int(func(args))


if __name__ == "__main__":
    raise SystemExit(main())
